    {
      "ids": ["SAF-02", "GRN-07"],
      "type": "logical",
      "description": "Executing a Minimal Risk Maneuver within 5 seconds (SAF-02) may conflict with minimizing energy usage during critical failures (GRN-07), as the maneuver may require more energy."
    },
    {
      "ids": ["SAF-04", "EFF-07"],
      "type": "logical",
      "description": "Minimizing jerk to ensure passenger comfort (SAF-04) may conflict with prioritizing smoothness during emergency maneuvers (EFF-07), as relaxing jerk limits could be necessary."
    },
    {
      "ids": ["SAF-07", "EFF-07"],
      "type": "logical",
      "description": "Emergency protocols to relax smoothness constraints (SAF-07) may conflict with prioritizing smoothness during emergencies (EFF-07), leading to potential safety risks."
    }
